def same_address(a: Address, b: Address) -> bool:
    """Loose equality used to detect repeat shipping destinations."""
    def key(x: Address) -> tuple:
        return (x.country, normalize_postcode(x.postcode, x.country), x.line1.lower().strip())
    return key(a) == key(b)
